  (* [comment removed for export] *)
  Lemma asc_ro_keep : forall LB LF m1 W XS m m' ioc regb cfgb,
    as_RFS H LF m1 -> Forall appw W -> Forall (fs_scratch H LF) XS ->
    fsobj H LF (ioc + 8) 8 -> aapp (ioc + 8) 8 -> (ioc + 8) mod 8 = 0 -> fsobj H LF cfgb NEWSZ_CFG -> rblock_range cfgb NEWSZ_CFG ->
    disjoint_from W (ioc + 8) 8 -> disjoint_from W cfgb NEWSZ_CFG -> disjoint_from W 0x119000 (0x12a180 - 0x119000) ->
    disjoint_from W AG_STACK_CHK_GUARD 8 ->
    munch (W ++ XS) m m' -> wmono bsegs m m' ->
    ro_cells bsegs m (ioc + 8) [C8 (wz regb)] -> accessible m (ioc + 8) 8 -> AConfigSvc LB m cfgb (cfg_hdr ioc) ->
    AXStatics2 m -> ACanaryReads m -> acanary m ->
    ro_cells bsegs m' (ioc + 8) [C8 (wz regb)] /\ accessible m' (ioc + 8) 8 /\ AConfigSvc LB m' cfgb (cfg_hdr ioc)
