  (* [comment removed for export] *)
  Lemma acfg_facts : forall LB m cfgb ioc, AConfigSvc LB m cfgb (cfg_hdr ioc) -> 0 <= ioc < 2^64 ->
    ro_cells bsegs m cfgb [C8 (wz AVP_CONFIG_SVC)] /\ ro_cells bsegs m (cfgb + O_CFG_HINT) [C4 (wz 4294967295)]
    /\ accessible m cfgb SZ_CFG /\ aapp cfgb SZ_CFG /\ cfgb mod 16 = 0 /\ rblock_range cfgb NEWSZ_CFG
    /\ ro_cells bsegs m cfgb (SvcHdrCells (cfg_hdr ioc)).
  Proof.
    intros LB m cfgb ioc (p & j4 & j7 & IN & C & E1 & E2 & RB & AD) IR.
    pose proof (rblock_bounds _ _ RB) as (Q0 & QN & QTOP & QIMG & QHI & Q8). pose proof RB as (_ & Q16 & _ & APC & _).
    apply (proj1 (rw_cells_app _ _ _ (SvcHdrCells _) _)) in C. destruct C as [C0 C1]. cbn [cells_size csize Nat.add SvcHdrCells] in C1.
    apply (proj1 (rw_cells_app _ _ _ [_; _] _)) in C1. destruct C1 as [C1 _].
    split; [| split; [| split; [| split; [| split; [exact Q16| split; [exact RB| exact (proj1 C0)]]]]]].
    - pose proof (rw_cells_ro_cell _ _ _ _ 0 _ C0 eq_refl) as K. rewrite Z.add_0_r in K. unfold cfg_hdr in K. exact K.
    - pose proof (rw_cells_ro_cell _ _ _ _ 0 _ C1 eq_refl) as K. unfold O_CFG_HINT. replace (cfgb + Z.of_nat 48 + Z.of_nat 0) with (cfgb + 48) in K by lia.
      replace (2 ^ 32 - 1) with 4294967295 in K by reflexivity. exact K.
    - eapply addressable_accessible with (A := cfgb) (n := NEWSZ_CFG); [exact AD| lia| unfold SZ_CFG, NEWSZ_CFG; lia| unfold NEWSZ_CFG, AAPP_HI in *; lia].
    - eapply aapp_sub; [exact APC| lia| unfold SZ_CFG, NEWSZ_CFG; lia].
  Qed.

  Lemma acfg_chain : forall LB m cfgb ioc, AConfigSvc LB m cfgb (cfg_hdr ioc) -> AXStatics2 m -> 0 <= ioc < 2^64 ->
    ASvcChain m cfgb [cfg_elt ioc cfgb].
