  Lemma acfg_find : forall ioc cfgb, find_svc AL_TYPEID_CONFIG 0 ATI_NAME_CONFIG [cfg_elt ioc cfgb] = cfgb.
  Proof. intros. cbn [find_svc]. replace (keys_match AL_TYPEID_CONFIG 0 ATI_NAME_CONFIG (cfg_elt ioc cfgb)) with true by (vm_compute; reflexivity). reflexivity. Qed.

